def resolve(root: Path, path: str | Path) -> Path:
    candidate = Path(path).expanduser()
    return candidate if candidate.is_absolute() else root / candidate


def resolve_under_root(root: Path, path: str | Path, *, label: str) -> Path:
    resolved = resolve(root, path).resolve()
    try:
        resolved.relative_to(root)
    except ValueError as exc:
        raise SystemExit(f"{label} must be under repository root: {resolved}") from exc
    return resolved


def validate_executable_path(root: Path, value: str | Path, *, label: str) -> str:
    path = resolve(root, value)
    # Preserve virtualenv launcher paths such as .venv/bin/python. Calling
    # Path.resolve() here follows the symlink to /usr/bin/python3.12 and causes
    # Python to drop the virtualenv site-packages at subprocess startup.
    absolute_path = path if path.is_absolute() else Path.cwd() / path
    if not absolute_path.is_file() or not os.access(absolute_path, os.X_OK):
        raise SystemExit(f"{label} must exist and be executable: {absolute_path}")
    return str(absolute_path)


def validate_script_path(root: Path, value: str | Path, *, label: str) -> Path:
    path = resolve(root, value).resolve()
    if not path.is_file():
        raise SystemExit(f"{label} must be a file: {path}")
    return path


def resolve_cli_command(root: Path, command: Sequence[str | Path]) -> list[str]:
    printable = [str(part) for part in command]
    if not printable:
        return printable
    if printable[0] == "hf":
        venv_hf = root / ".venv" / "bin" / "hf"
        if venv_hf.is_file() and os.access(venv_hf, os.X_OK):
            printable[0] = str(venv_hf)
        elif found := shutil.which("hf"):
            printable[0] = found
    return printable


