    func snapshot() -> AgentWorkflowSnapshot {
        let copied: [AgentWorkflowEvent]
        lock.lock()
        copied = events
        lock.unlock()

        var active: [String: AgentWorkflowEvent] = [:]
        var last: [String: AgentWorkflowEvent] = [:]
        var completed: [String: Int] = [:]
        var durations: [String: Int] = [:]
        var fallbackCount = 0
        var errorCount = 0

        func clearActive(for event: AgentWorkflowEvent, slotKey: String) {
            active[slotKey] = nil
            let matchingKeys = active.compactMap { key, activeEvent -> String? in
                if let turnID = event.turnID, !turnID.isEmpty, activeEvent.turnID == turnID {
                    return key
                }
                if event.turnID == nil,
                   let conversationID = event.conversationID,
                   !conversationID.isEmpty,
                   activeEvent.conversationID == conversationID {
                    return key
                }
                return nil
            }
            for key in matchingKeys {
                active[key] = nil
            }
        }

        for event in copied {
            let key = event.slot.rawValue
            last[key] = event
            switch event.status {
            case .running:
                active[key] = event
            case .done:
                clearActive(for: event, slotKey: key)
                completed[key, default: 0] += 1
            case .failed:
                clearActive(for: event, slotKey: key)
                errorCount += 1
            case .cancelled:
                clearActive(for: event, slotKey: key)
            case .fallback:
                clearActive(for: event, slotKey: key)
                fallbackCount += 1
            case .info:
                break
            }
            if let durationMs = event.durationMs {
                durations[key, default: 0] += durationMs
            }
        }

        return AgentWorkflowSnapshot(
            generatedAt: Date(),
            events: copied,
            activeBySlot: active,
            lastEventBySlot: last,
            completedCountBySlot: completed,
            fallbackCount: fallbackCount,
            errorCount: errorCount,
            totalDurationMsBySlot: durations
        )
    }

