    }

    private struct StructuredAction: Encodable {
        let tool: String
        let args: AgentJSONArguments
    }

    var dedupeKey: String {
        let argsStr = args.keys.sorted()
            .map { "\($0)=\(args[$0]?.stringValue ?? "")" }
            .joined(separator: "&")
        return tool + "|" + argsStr
    }

    var displayContent: String {
        if args.isEmpty { return "\(tool)()" }
        let argsStr = args.keys.sorted()
            .map { "\($0)=\(args[$0]?.stringValue ?? "")" }
            .joined(separator: ", ")
        return "\(tool)(\(argsStr))"
    }

