        guard cutoff > 0 else { return "" }

        let safeRawPrefix = String(rawBuffer.prefix(cutoff))
        guard !safeRawPrefix.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return ""
        }

