    private static func hasMeaningfulTarget(_ text: String) -> Bool {
        let stopWords: Set<String> = [
            "a", "an", "the", "my", "me", "to", "for", "with", "about", "on", "at", "in",
            "this", "that", "it", "them", "please", "can", "you", "i", "want", "need", "help"
