        progresses[model.id] = DownloadProgress(fractionCompleted: progresses[model.id]?.fractionCompleted ?? 0, bytesReceived: progresses[model.id]?.bytesReceived ?? 0, totalBytes: model.sizeBytes, state: .downloading)
