    func shouldDegrade(category: CPUWatchdogCategory) -> Bool {
        let now = ProcessInfo.processInfo.systemUptime
        lock.lock()
        prune(now: now)
        let total = rollingTotal(category: category, now: now)
        lock.unlock()
