    private func truncationLabel(_ s: AttachmentRenderState) -> String {
        guard s.totalChars > 0 else { return "Truncated" }
        let pct = Int((Double(s.includedChars) / Double(s.totalChars)) * 100)
        return "Truncated — \(max(1, pct))% included"
    }
}

