            position = .region(MKCoordinateRegion(
                center: coordinate,
                latitudinalMeters: 1200,
                longitudinalMeters: 1200
            ))
            errorMessage = nil
        } catch {
            errorMessage = "Map search failed: \(error.localizedDescription)"
        }
    }
}

