private func percentText(_ value: Double) -> String {
    String(format: "%.0f%%", value * 100)
}

private func durationText(_ seconds: Double) -> String {
    if seconds >= 60 {
        return String(format: "%.1fm", seconds / 60)
    }
    return String(format: "%.1fs", seconds)
}


