            if issuesAfter > issuesBefore {
                status = "fail"
                if errorMessage == nil {
                    errorMessage = "One or more XCT assertions failed during this step."
                }
            }

            let stepEnd = Date()
            let durationMs = Int(stepEnd.timeIntervalSince(stepStart) * 1_000)
