                    status: status,
                    startedAt: formatter.string(from: stepStart),
                    endedAt: formatter.string(from: stepEnd),
                    durationMs: durationMs,
                    indicators: [
                        "durationSeconds": durationSeconds,
                        "eventsPerSecond": 1.0 / durationSeconds
                    ],
                    errorMessage: errorMessage
                )
            )

