      --windows-iso) need_value "$1" "${2:-}"; windows_iso="$2"; shift 2;;
      --ubuntu-iso) need_value "$1" "${2:-}"; ubuntu_iso="$2"; shift 2;;
      --macos-asset) need_value "$1" "${2:-}"; macos_asset="$2"; include_osx_kvm=1; shift 2;;
