  [[ "$dry_run" == "1" ]] && dry_args+=(--dry-run)
  [[ "$secure_boot" == "1" ]] && secure_args+=(--secure-boot)
  [[ "$yes_destroy" == "1" ]] && destroy_args+=(--yes-destroy)

