    failures: list[dict[str, Any]] = []
    repair_samples = behavior_audit.get("repairSamples")
    if isinstance(repair_samples, list):
        for sample in _iter_dicts(repair_samples):
            if not _is_actionable_behavior_repair_sample(sample):
                continue
